    "question": "【シナリオ：カスタマーサポート解決エージェント】\n前提: Claude Agent SDKを用い、以下のツール群を持つエージェントが本番運用されている。\n- `get_customer(customer_id)`: 顧客プロファイル取得\n- `verify_identity(customer_id, token)`: 本人認証完了フラグ設定\n- `lookup_order(order_id)`: 注文詳細・配送ステータス取得\n- `process_refund(order_id, amount)`: 返金実行（高リスク）\n- `escalate_to_human(reason, priority)`: 有人オペレーターへ転送\n\n状況・課題:\n顧客から「注文商品が未着のため直ちに全額返金してほしい」と強い要求があった。エージェントは `verify_identity` による認証を行わず、また `lookup_order` による配送状態の確認も行わないまま、直接 `process_refund` を実行してしまい、重大なコンプライアンス違反となった。\nシステムプロンプトには「返金前に必ず本人認証と注文確認を行うこと」と明記されていたが、顧客の強い感情表現に影響されルールが形骸化した。\n\n問い:\nモデルの確率的判断に依存せず、必要な事前処理が完了するまで特定ツールの実行を「決定論的（確実）に防止」するためのアーキテクチャ設計として、最も適切なものはどれか？",
