    "explanation": "【公式アーキテクチャ解説】\n正解は「コード側の状態管理で前提条件完了を検証し、未完了時はツール実行を遮断するPrerequisite Gateを導入する手法」です。\n\nAnthropicの公式ベストプラクティスにおいて、高リスクなアクション（送金、返金、データ削除等）の前提条件順序は、LLMのプロンプトによる指示（確率的制御）だけに依存してはなりません。\nアプリケーションコード側（またはHooks）でセッション状態（例: `state.is_verified === true && state.order_checked === true`）を管理し、条件が満たされない場合は物理的にツールの実行を拒否する「Prerequisite Gate（前提条件ゲート）」または「Programmatic Enforcement」を設けることが必須要件とされています。\n\n⚠️ 引っかけポイント: プロンプトの強調、スキーマのdescription追記、temperatureの低下、Few-shotの追加はいずれも「モデルの指示遵守率を統計的に向上させる」効果はありますが、「100%確実な決定論的防止」にはならず、プロンプトインジェクション等で破綻します。",
