    "question": "【シナリオ：Claude Code によるコード生成】\n前提: エンタープライズ開発チーム（50名）が、リポジトリ内の共通開発ツールとして Claude Code CLI を導入することになった。\nチーム内には「全社共通のセキュリティ規約（例: APIキー直接記述の禁止）」と、「各リポジトリ固有のビルド・テスト手順（例: `npm run test:unit`）」の双方が存在する。\n\n状況・課題:\n開発者が各自のローカル端末で Claude Code を実行した際、プロジェクト固有のコーディング規約やテスト手順が遵守されず、リポジトリごとに品質のバラつきが生じる問題が発生した。\n\n問い:\nClaude Code の設定管理アーキテクチャにおいて、リポジトリ固有の指示をチーム全員でバージョン管理し、確実に適用させるための最も適切な構成はどれか？",
