    "question": "【シナリオ：Claude Code によるコード生成】\n前提: 開発チームはCIパイプラインや非対話バッチ環境において、Claude Code に自動でコードの修正とテスト実行を行わせる仕組みを構築している。\n非対話実行のため、コマンド実行のたびに発生する「承認プロンプト（Y/n）」をバイパスするフラグ `--dangerously-skip-permissions` を付与して実行する必要がある。\n\n状況・課題:\nこのフラグをホストOS（開発者の端末や本番ビルドサーバー）上で直接実行すると、悪意あるコードやモデルの誤判断によってホスト上の重要ファイル削除（例: `rm -rf /`）や機密環境変数の外部送信が発生する壊滅的なリスクがある。\n\n問い:\n`--dangerously-skip-permissions` を実務で安全に運用するために、アーキテクトが講じるべき最も堅牢なサンドボックス設計はどれか？",
