    "question": "【シナリオ：Claude Code によるコード生成】\n前提: Claude Code に既存機能のバグ修正を依頼した。エージェントは「コード修正 -> テスト実行 -> エラー解析 -> コード再修正」という自己修復ループ（Self-Healing Agentic Loop）を開始した。\n\n状況・課題:\nテストコード側に根本的な設計不備があり、どのようなプロダクトコード修正を行ってもテストが絶対に通過しない状態であった。\nエージェントはこの事実に気づかず、修正とテスト実行を何百回も繰り返し、APIトークン消費とCPUリソースが無限に消費され続ける「無限ループ障害」が発生した。\n\n問い:\nエージェントの自己修復ループにおいて、コスト爆発と無限ループを決定論的に防止するための「オーケストレーション制御」として、最も適切なものはどれか？",
