    "explanation": "【公式アーキテクチャ解説】\n正解は「最大反復回数（Max Turns）と全体タイムアウトを設定し、規定回数内に解決しない場合はループを中断して失敗ログを出す設計」です。\n\n自律型エージェントループ（Agentic Loop / Evaluator-Optimizer Loop）を設計する際の必須防護柵が「Circuit Breaker（サーキットブレーカー / 上限制御）」です。\n具体的には：\n1. `max_turns`（最大反復回数: 例: 5〜10回）のハードリミット\n2. セッション全体のタイムアウト（例: 15分）\n3. トークン消費バジェットの上限\nを設定し、これを超過した場合は即座にループを中断して状態をセーブし、人間にエスカレーションまたはエラーログを出力します。\n\n⚠️ 引っかけポイント: temperatureの引き上げは無限ループをより混沌とさせるだけであり、テストの改ざんやコード削除はシステムの破壊行為です。",
