    "question": "【シナリオ：マルチエージェント調査システム】\n前提: Orchestrator が調査を迅速に進めるため、5つの専門サブトピック（技術動向、市場シェア、特許状況、財務状況、人事施策）を5台の `Research Worker Agent` に割り当てた。\n\n状況・課題:\nOrchestrator が5台のワーカーを非同期で完全同時に一斉起動したところ、全ワーカーが同一のClaude APIエンドポイントおよび同一の外部検索APIに対して同時にリクエストを集中させた。\nその結果、APIのレートリミット（HTTP 429 Too Many Requests）が一斉に発生し、全ワーカーのリクエストが同時に失敗する「サンダリングハード問題」が発生した。\n\n問い:\n並列エージェント実行（Parallelization）において、同時リクエストの集中によるレートリミット障害を防止するためのアーキテクチャ設計はどれか？",
