    "explanation": "【公式アーキテクチャ解説】\n正解は「ワーカーの同時実行数セマフォによる流量制限と、リトライ時のランダムな揺らぎ（Jitter）付き指数バックオフを導入する設計」です。\n\n並列エージェント実行（Parallelization）をスケールさせる際の重要プラクティスです。\n1. 【同時実行制御】同時並行で走るワーカー数（Concurrency Limit）をセマフォやキュー（例: p-limit / Celery）で制限し、組織のAPIクォータ内に収める。\n2. 【Jitter付き指数バックオフ】一時的な429や529エラーが発生した際、全クライアントが同一秒数後に一斉リトライして再び過負荷を起こす「サンダリングハード問題」を防ぐため、ランダムな待機時間（Jitter）を加えた指数バックオフで再試行する。\n\n⚠️ 引っかけポイント: 直列実行への後退は並列化のメリット（高速化）を破棄し、ノーウェイトの猛烈リトライはサービス拒否攻撃（DoS）となり即時アカウント凍結につながります。",
