    "explanation": "【公式アーキテクチャ解説】\n正解は「AI解析用ジョブを本番デプロイジョブから完全に分離し、デプロイ用シークレットを一切注入しない最小権限ランナーとする設計」です。\n\nCI/CDにおけるセキュリティの黄金律は「Job Isolation（ジョブの分離）」と「最小権限の原則」です。\nAIコードレビューやPR解析を実行するジョブには、そもそも `AWS_SECRET_ACCESS_KEY` や `DB_PASSWORD` といった高リスクな認証情報を環境変数として渡してはなりません（注入ゼロ）。\nAI解析ジョブにはAnthropic APIキー（あるいは一時的な低権限GitHubトークン）のみを渡し、本番デプロイ用の特権シークレットが必要なジョブは、コードレビューが通過し、人間が承認した後の「別ステージの保護されたワークフロージョブ」でのみ注入します。これにより、AIがインジェクション等で `env` をダンプしても漏洩するものが存在しません。\n\n⚠️ 引っかけポイント: プロンプト（CLAUDE.md）での禁止指示はモデルの誤動作や脱獄攻撃に対して無力です。",
