    "question": "【シナリオ：Claude Code の CI/CD 組み込み】\n前提: 大型リファクタリングのプルリクエストにおいて、変更されたファイル数が200ファイル、差分行数が合計10万行におよぶ巨大なPRが提出された。\n\n状況・課題:\nこの巨大な差分テキスト（git diff）を一括でClaudeのプロンプトに流し込もうとしたところ、入力コンテキスト長の上限を超過してAPIエラーが発生した。\nまた、仮にコンテキストに収まったとしても、全体を一括でレビューさせると各ファイルの細かいロジック欠陥を見落とす「大雑把なレビュー」になってしまう。\n\n問い:\n巨大なプルリクエストに対して、コンテキスト制限を回避し、かつ精度の高いコードレビューを確実に実行するためのアーキテクチャ設計はどれか？",
