    "question": "【シナリオ：Claude Code の CI/CD 組み込み】\n前提: オープンソースプロジェクトまたは外部協力会社と共同開発しているリポジトリにおいて、外部のフォーク（Fork）リポジトリから作成されたプルリクエストに対しても自動でAIコードレビューを実行したい。\n\n状況・課題:\nGitHub Actions のトリガーとして `pull_request_target` を不用意に使用し、フォーク元の信頼できないPRコードをチェックアウトした上で、リポジトリの書き込み権限トークンやAnthropic APIキーを環境変数に読み込ませていた。\n悪意ある攻撃者がPR内に悪意あるコードを仕込み、CIランナー上でシークレットを窃取する「Pwned Pipeline（ワークフロー乗っ取り）」攻撃の脆弱性が発覚した。\n\n問い:\nフォーク元の信頼できないコードに対するAIレビューを、安全性を完全に担保して実行するためのCIワークフロー設計はどれか？",
