    "question": "【シナリオ：構造化データ抽出】\n前提: 各種サプライヤーから送られてくる非定型のPDF請求書（Invoice）から、取引先名、請求金額、明細行リスト（品目、単価、数量、小計）を抽出し、後続の会計ERPシステムに直接投入するためのJSON形式で出力させるパイプラインを構築している。\n\n状況・課題:\nモデルに対して「JSON形式で出力せよ」とプロンプトで指示していたが、時折「はい、請求書データを抽出したJSONは以下の通りです：```json ... ```」という前置きの挨拶文やMarkdown装飾が含まれてしまい、後続のプログラム（JSON.parse）が構文エラーでクラッシュする障害が発生した。\n\n問い:\n前置きの会話文やMarkdownバッククォートを完全に排除し、Claudeから純粋なJSONオブジェクトのみを確実に先頭から出力させるためのAPIテクニックはどれか？",
