    "explanation": "【公式アーキテクチャ解説】\n正解は「XMLタグ（<instructions>, <schema>, <contract_document>）を用いて各要素の境界を明確に区切る構造化プロンプト設計」です。\n\nAnthropic公式プロンプトエンジニアリングの最重要原則が「XMLタグによる明確な構造化」です。\nプロンプト内で：\n- `<instructions>`: 抽出のルールや注意点\n- `<schema>`: 期待するJSON Schemaの定義\n- `<contract_document>`: 抽出対象となる生の契約書テキスト\nのようにXMLタグで厳格にカプセル化（境界設定）を行います。\nこれにより、Claudeは「どこからどこまでがシステム指示で、どこが単なる入力データなのか」を完璧に峻別でき、契約書内に紛らわしい文言があってもプロンプトインジェクションや指示の混同を完全に回避できます。\n\n⚠️ 引っかけポイント: 改行の削除は可読性と構文構造を破壊し、ハイフンの連打やエスペラント語翻訳は意味をなしません。",
