    "question": "【シナリオ：金融機関マルチクラウド統合基盤】\n前提: 金融機関の市場調査部門において、毎日数万ページのPDF（世界各国の経済レポートや中央銀行の議事録）を要約・構造化している。\n\n状況・課題:\nプロンプトの先頭に「金融アナリストとしての行動指針」や「自社のコンプライアンス規約（約3,000トークン）」が固定で記述されており、毎リクエストで同じ長大なコンテキストがAPIへ送信されているため、不要な入力トークンコストが累積していた。\n\n問い:\n固定の規約や指示部分に対する入力トークン課金を大幅に削減し、初回レスポンス速度を高速化するためのAPI最適化機能はどれか？",
