    "question": "【シナリオ：医療・製薬高リスクAIガバナンス】\n前提: 製薬企業の取締役会（Board of Directors）およびリスク管理委員会に対して、最高AI責任者（CAIO）およびチーフアーキテクトが全社のAI導入状況とリスク状況を定期報告する。\n\n状況・課題:\n経営陣（取締役）はディープラーニングの数学的詳細やTransformerのAttention機構の数式を理解していない。\n技術者が専門用語だらけのエンジニアリング資料をそのまま持ち込んだため、経営陣がリスクの重大性を理解できず、必要な安全対策予算の承認が得られなかった。\n\n問い:\n取締役会および経営層に対してAIリスクを説明し、ガバナンスの意思決定を仰ぐための最も適切な報告・ダッシュボード設計はどれか？",
