    "question": "【シナリオ：LLM評価・MLOpsパイプライン】\n前提: ペアワイズ比較（Model A vs Model B）による自動評価パイプラインを運用している。\n\n状況・課題:\n実験データを分析したところ、ジャッジを担当しているLLMが「中身の品質に関わらず、左側（最初）に提示された回答Aに投票する確率が70%を超える」という深刻な「位置バイアス（Position Bias / Order Bias）」が存在することが判明した。\nこのままでは、左側に置かれたモデルが不当に高く評価され、誤ったモデル採用判断を下してしまう。\n\n問い:\nLLMジャッジに固有の位置バイアス（Position Bias）を数学的・統計的に完全に相殺・中和するための標準的評価プロトコルはどれか？",
