    "explanation": "【公式エンタープライズ解説】\n正解は「タスクに応じた詳細な評価基準（Rubric）と多段階の評価ステップ（CoT）をモデル自身に生成させ、確率加重平均スコアを算出する手法」です。\n\nLLM-as-a-Judgeの最先端標準フレームワーク「G-Eval（Liu et al.）」のアーキテクチャです。\nG-Evalの4段階プロセス：\n1. **評価基準のプロンプト化**: タスクの定義と評価観点（例: 一貫性、事実性）。\n2. **CoT評価ステップの自動生成**: モデル自身に「ステップ1: 文書全体のメインの論点を特定せよ」「ステップ2: 要約がその論点をカバーしているか検証せよ」という多段階の推論思考チェーン（Evaluation Steps）を生成させる。\n3. **推論とスコア判定**: このステップに沿って深く考察させた上でスコアを出力。\n4. **確率加重平均（Probability-Weighted Score）**: 出力トークン（1〜5点）の対数確率（logprobs）を用いて期待値を計算し、滑らかで信頼性の高い連続値スコアを算出する。\nこれにより、人間の専門家評価と極めて高い相関関係を達成します。\n\n⚠️ 引っかけポイント: 逆読みや素数判定、翻訳ループは学術的G-Evalの仕様とは一切無関係です。",
