    "question": "【シナリオ：LLM評価・MLOpsパイプライン】\n前提: 全社の開発者が共有する評価基盤において、モデルやプロンプトの改修時に自動実行される「ゴールデンテストセット（Golden Test Set）」を整備している。\n\n状況・課題:\nテストセットが、開発者が思いつきで作った「10件の極めて簡単で典型的な質問」だけで構成されていたため、テストが毎回100%パスするにもかかわらず、本番リリース後にエッジケース（複雑な複合指示や境界値）でエラーが多発する事態となった。\n\n問い:\n本番環境の信頼性を真に保証する、高品質なゴールデンテストセットを構築・運用するためのベストプラクティスはどれか？",
