    "explanation": "【公式エンタープライズ解説】\n正解は「本番環境の失敗ログや多様なエッジケースを収集し、難易度・カテゴリ別に層化抽出して人間の専門家が正解を検証・更新し続ける設計」です。\n\nエンタープライズMLOpsにおけるゴールデンテストセット（Golden Dataset）の運用原則です。\n高品質なテストセットの条件：\n1. **多様性と層化（Stratified Diversity）**: 単純なハッピーパスだけでなく、曖昧な指示、敵対的入力、境界値データ、長文ドキュメントなど、カテゴリと難易度をバランスよく網羅。\n2. **本番ログからの継続的還元（Active Learning Loop）**: 本番環境でユーザーから低評価（Thumbs-down）された事例やエージェントが失敗したエッジケースをトリアージし、定期的にテストセットへ追加する。\n3. **人間による真実検証（Ground Truth Curation）**: 専門アナリストが期待される出力基準を定義・監査し、バージョン管理（Git / DVC）する。\n\n⚠️ 引っかけポイント: 10件の永久固定や同一クエリの無意味なコピペ増殖は、本番の品質を一切保証できません。",
