    "explanation": "【公式エンタープライズ解説】\n正解は「高精度NERや正規表現でPIIを可逆的プレースホルダー（[CREDIT_CARD_1]等）に置換して推論させ、返却時に社内セキュアVaultで復元する構成」です。\n\n機密情報の保護とLLMの文脈理解を両立させる業界標準パターンが「仮名化トークン置換（Pseudonymization / Tokenization）」です。\n1. APIゲートウェイの手前で、固有表現抽出（NER）および正規表現を用いてPIIを検出\n2. 一時的な一意プレースホルダー（例: `[CARD_NUM_A]`, `[CUSTOMER_NAME_1]`）に置換\n3. 置換マッピングテーブルをオンプレミス内の高セキュアなVault（またはKMSで暗号化されたRedis）に保持\n4. プレースホルダーを含むテキストをClaudeに入力して要約\n5. 要約結果を受け取った社内ゲートウェイで、Vaultのマッピングを参照して元の安全な表記へ復元（またはマスク維持）\nこの手法により、Claudeには一切の平文生データを渡すことなく、モデルの代名詞・名詞句の参照追跡能力を完全に活かすことができます。\n\n⚠️ 引っかけポイント: 全文字黒塗りは文脈破壊を招き、プロンプト指示頼みはコンプライアンス違反・情報漏洩の温床となります。",
