    "question": "【シナリオ：FinOps・キャパシティ最適化とLLM可観測性】\n前提: マイクロサービス群で構成された複雑なエンタープライズ検索アシスタントにおいて、ユーザーからの問い合わせに対する応答時間（E2Eレイテンシ）が従来の2.5秒から15秒へと突発的に悪化した。\nシステム経路には、Webフロントエンド、API Gateway、認可基盤、ベクトル検索エンジン（OpenSearch）、ガードレール検査、社内プロキシ、およびClaude API（Streaming）が存在する。\n\n状況・課題:\n各サービスチームが独立して運用されており、ログフォーマットが不統一なため、「どのコンポーネントで何ミリ秒消費されているのか」「Claudeの初回トークン生成（TTFT）が遅いのか、出力トークン数が増えた（TPOT）のか」を迅速に切り分けることができない。\n\n問い:\n分散システム全体にわたるボトルネックをミリ秒単位で可視化し、LLM特有のパフォーマンスメトリクスを追跡するための業界標準アーキテクチャはどれか？",
