    "explanation": "【公式エンタープライズ解説】\n正解は「12万トークンの判例とシステム指示をプロンプト先頭に配置し、末尾に`cache_control`ブレークポイントを設定してキャッシュ再利用する設計」です。\n\nAnthropic Prompt Cachingは、大規模な静的コンテキスト（ドキュメント、コードベース、システムプロンプト、ツール定義など）をサーバー側で5分間（TTL）キャッシュする画期的な機能です。\nキャッシュヒット時のメリット：\n- 入力トークンコストが通常価格の **10%（90%割引）** に削減\n- 初回トークン生成（TTFT）が最大 **80%以上高速化**\nキャッシュを有効にするための厳格な設計ルール：\n1. **静的プレフィックスの先頭配置**: プロンプト構造は「静的な大容量コンテキスト（先頭）」➜「動的なユーザーの質問（末尾）」の順序で配置する（プレフィックスが1文字でも異なるとキャッシュミスとなるため）。\n2. **キャッシュブレークポイント**: キャッシュ対象ブロックの末尾に `\"cache_control\": {\"type\": \"ephemeral\"}` を指定する。\n質問文を先頭に置いたりテキストをシャッフルするとキャッシュが一切効かなくなるため、プロンプト構造化の順序が決定的に重要です。\n\n⚠️ 引っかけポイント: 変動する質問文を先頭に配置するとキャッシュキーが毎回変わり全件キャッシュミスとなります。",
