    "question": "【シナリオ：FinOps・キャパシティ最適化とLLM可観測性】\n前提: グローバルな戦略コンサルティングファームが、企業のM&Aデューデリジェンス向けにClaude 3.7 Sonnet の「Extended Thinking（拡張思考）」を活用した高度財務モデリング支援システムを構築する。\nExtended Thinkingを有効化すると、モデルは最終回答を出力する前に複雑な多段階推論を「思考トークン（thinking tokens）」として内部展開し、人間レベルの難解な論理矛盾を自律解決できる。\n\n状況・課題:\nしかし、推論パラメータである `thinking.budget_tokens`（思考トークン予算）を無計画に設定すると、簡単な定型質問でも長時間の思考が発生して応答レイテンシとAPIコストが跳ね上がり、逆に過少に設定すると複雑な財務分析の途中で思考が強制打ち切り（truncated）されて計算精度が著しく低下する。\n\n問い:\n推論品質の最大化と、コスト・レイテンシのFinOps最適化を両立するための `budget_tokens` 設計・制御方針として、最も適切なものはどれか？",
