    "explanation": "【公式エンタープライズ解説】\n正解は「タスク難易度に応じて動的に思考予算を設定し、定型処理は無効化、複雑な推論は適切なトークン上限を設定して早期停止条件と組み合わせる設計」です。\n\nClaude 3.7 Sonnet で導入された Extended Thinking では、アーキテクトが推論の深さを制御するための `budget_tokens`（思考予算トークン数）の設計が極めて重要です。\nFinOpsとパフォーマンスを両立するベストプラクティス：\n1. **動的ルーティング（Adaptive Budgeting）**:\n   - 定型的なFAQや単純分類: Extended Thinkingを無効化（`thinking`パラメータなし）し、高速かつ最低コストで処理。\n   - 中程度の推論（文書要約・コードレビュー）: 2,000〜4,000 トークンの控えめな予算を割り当て。\n   - 超高難度推論（M&A財務分析・アルゴリズム設計）: 8,000〜16,000 トークン以上の十分な思考予算を確保。\n2. **思考トークンの課金理解**: 思考トークンは通常の出力トークンと同じ料金で課金されるため、不要な長考をプロンプト側の明確なゴール定義で抑制することがコストコントロールの要となります。\n\n⚠️ 引っかけポイント: 全タスクへの最大予算一律付与はコストの爆発を招き、1トークン固定はAPI仕様上エラー（最小1,024トークン推奨）または意味がありません。",
